<?php require_once '../functions.php';need_admin();$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){if(isset($_POST['delete'])){$pdo->prepare('DELETE FROM symptoms WHERE id=?')->execute([(int)$_POST['id']]);$msg='Gejala dihapus.';}else{$id=(int)($_POST['id']??0);$vals=[trim($_POST['code']),trim($_POST['name']),trim($_POST['description']),$_POST['category'],isset($_POST['active'])?1:0];if($id)$pdo->prepare('UPDATE symptoms SET code=?,name=?,description=?,category=?,active=? WHERE id=?')->execute([...$vals,$id]);else $pdo->prepare('INSERT INTO symptoms(code,name,description,category,active) VALUES(?,?,?,?,?)')->execute($vals);$msg='Gejala tersimpan.';}}$edit=null;if(isset($_GET['edit'])){$q=$pdo->prepare('SELECT * FROM symptoms WHERE id=?');$q->execute([(int)$_GET['edit']]);$edit=$q->fetch();}$rows=$pdo->query('SELECT * FROM symptoms ORDER BY category,code')->fetchAll();header_html('Kelola gejala');include '_nav.php';?><section class="page-head"><span class="eyebrow">BASIS PENGETAHUAN</span><h1>Gejala tanaman</h1><p>Gejala umum tampil pada tahap awal; gejala khusus menjadi pertanyaan setelah penyakit terpilih.</p></section><?php if($msg):?><div class="success"><?=e($msg)?></div><?php endif;?><section class="card admin-form"><h2><?=$edit?'Ubah gejala':'Tambah gejala'?></h2><form method="post" class="form form-grid"><input type="hidden" name="id" value="<?=$edit['id']??''?>"><label>Kode<input name="code" value="<?=e($edit['code']??'')?>" required placeholder="G001"></label><label>Nama gejala<input name="name" value="<?=e($edit['name']??'')?>" required></label><label>Kategori<select name="category"><option value="umum" <?=($edit['category']??'')==='umum'?'selected':''?>>Umum</option><option value="khusus" <?=($edit['category']??'')==='khusus'?'selected':''?>>Khusus</option></select></label><label class="span2">Keterangan<input name="description" value="<?=e($edit['description']??'')?>"></label><label class="inline"><input type="checkbox" name="active" <?=!isset($edit['active'])||$edit['active']?'checked':''?>> Aktif</label><button class="button">Simpan gejala</button></form></section><div class="table-wrap card"><table><thead><tr><th>Kode</th><th>Gejala</th><th>Kategori</th><th>Aktif</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['code'])?></td><td><b><?=e($r['name'])?></b><small class="block"><?=e($r['description'])?></small></td><td><?=e($r['category'])?></td><td><?=$r['active']?'Ya':'Tidak'?></td><td><a href="?edit=<?=$r['id']?>">Ubah</a> <form class="inline-form" method="post" onsubmit="return confirm('Hapus gejala ini?')"><input type="hidden" name="id" value="<?=$r['id']?>"><button name="delete" value="1" class="link-danger">Hapus</button></form></td></tr><?php endforeach;?></tbody></table></div><?php footer_html();?>
